@startuml

class Customer {
  + name : string
  + phoneNumber : string
}

class Table {
  + numberOfSeats : int
  + isSmokingArea : boolean
}

class Reservation {
  + reservationDate : date
  + reservationTime : time
  + numberOfPeople : int
}

class Waiter {
  + name : string
  + yearsOfService : int
}

class Bill {
  + totalAmount : double
}

class Dish {
  + name : string
  + unitPrice : double
}

class BillItem {
  + quantity : int
}

Customer "1" -- "0..*" Reservation
Reservation "*" -- "1..*" Table
Reservation "*" -- "0..1" Waiter
Waiter "1" -- "0..*" Reservation
Customer "1" -- "0..*" Bill
Bill "1" *-- "1..*" BillItem
BillItem "*" -- "1" Dish

@enduml

